export function Opacity({
  opacityPct = {{opacityPct}},
  elementColor = "{{elementColor}}",
  showBehind = {{showBehind}},
  size = {{size}},
}) {
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 300 }}>
      <div style={{ position: "relative", height: 130, background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden" }}>
        {showBehind && (
          <div style={{ position: "absolute", width: 60, height: 60, borderRadius: 8,
            background: "repeating-linear-gradient(45deg, #E8A020, #E8A020 6px, transparent 6px, transparent 12px)" }} />
        )}
        <div style={{ position: "relative", width: size, height: size, background: elementColor, opacity: opacityPct / 100, borderRadius: 10 }} />
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>opacity: {opacityPct}%</p>
    </div>
  );
}
